struct NativeDedicatedWorker {
    url: String,
    runtime: NativeJavaScriptRuntime,
    import_script_counts: BTreeMap<String, usize>,
    module_sources: BTreeMap<String, String>,
    is_module: bool,
    is_shared: bool,
    next_module_turn: AtomicU64,
}

#[derive(Debug, Clone)]
struct NativeMessagePortRoute {
    worker_id: u32,
}

impl NativeDedicatedWorker {
    fn evaluate_initial(
        &self,
        worker_id: u32,
        source: &str,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        if self.is_shared && self.is_module {
            self.runtime.evaluate_shared_worker_module(
                worker_id,
                &self.url,
                &self.url,
                source,
                &self.module_sources,
            )
        } else if self.is_shared {
            self.runtime.evaluate_shared_worker(
                worker_id,
                &self.url,
                source,
                &self.import_script_counts,
            )
        } else if self.is_module {
            self.runtime.evaluate_worker_module(
                worker_id,
                &self.url,
                &self.url,
                source,
                &self.module_sources,
            )
        } else {
            self.runtime
                .evaluate_worker(worker_id, &self.url, source, &self.import_script_counts)
        }
    }

    fn evaluate_turn(
        &self,
        worker_id: u32,
        source: &str,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        if self.is_shared && self.is_module {
            let turn = self.next_module_turn.fetch_add(1, Ordering::Relaxed);
            let module_name = format!("{}#glass-shared-worker-turn-{turn}", self.url);
            self.runtime.evaluate_shared_worker_module(
                worker_id,
                &self.url,
                &module_name,
                source,
                &self.module_sources,
            )
        } else if self.is_shared {
            self.runtime.evaluate_shared_worker(
                worker_id,
                &self.url,
                source,
                &self.import_script_counts,
            )
        } else if self.is_module {
            let turn = self.next_module_turn.fetch_add(1, Ordering::Relaxed);
            let module_name = format!("{}#glass-worker-turn-{turn}", self.url);
            self.runtime.evaluate_worker_module(
                worker_id,
                &self.url,
                &module_name,
                source,
                &self.module_sources,
            )
        } else {
            self.runtime
                .evaluate_worker(worker_id, &self.url, source, &self.import_script_counts)
        }
    }

    fn evaluate_turn_with_event(
        &self,
        worker_id: u32,
        dispatch: NativeWorkerDispatch<'_>,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        let empty_import_script_counts = BTreeMap::new();
        let import_script_counts = if self.is_module {
            &empty_import_script_counts
        } else {
            &self.import_script_counts
        };
        let bootstrap = if self.is_shared {
            shared_worker_bootstrap(
                worker_id,
                &self.url,
                self.runtime.now_ms(),
                import_script_counts,
                self.is_module,
            )?
        } else {
            worker_bootstrap(
                worker_id,
                &self.url,
                self.runtime.now_ms(),
                import_script_counts,
                self.is_module,
            )?
        };
        let module_name = if self.is_module {
            let turn = self.next_module_turn.fetch_add(1, Ordering::Relaxed);
            let prefix = if self.is_shared {
                "glass-shared-worker-event"
            } else {
                "glass-worker-event"
            };
            Some(format!("{}#{prefix}-{turn}", self.url))
        } else {
            None
        };
        if self.is_module {
            self.runtime.set_module_sources(self.module_sources.clone());
        }
        self.runtime
            .evaluate_worker_source_with_bootstrap_and_event(
                worker_id,
                &self.url,
                module_name.as_deref(),
                "undefined;",
                bootstrap,
                false,
                false,
                Some(dispatch),
            )
    }

    fn evaluate_shared_connect(
        &self,
        worker_id: u32,
        transfer_port: &NativeMessagePortTransfer,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        self.runtime.evaluate_shared_worker_connect(
            worker_id,
            &self.url,
            transfer_port,
            self.is_module,
        )
    }

    fn evaluate_websocket_event(
        &self,
        worker_id: u32,
        socket_id: u32,
        event: &serde_json::Value,
        csp_violations: &[NativeCspViolation],
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        self.evaluate_turn_with_event(
            worker_id,
            NativeWorkerDispatch::WebSocket {
                socket_id,
                payload: event,
                csp_violations,
            },
        )
    }

    fn evaluate_event_source_event(
        &self,
        worker_id: u32,
        source_id: u32,
        event: &serde_json::Value,
        csp_violations: &[NativeCspViolation],
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        self.evaluate_turn_with_event(
            worker_id,
            NativeWorkerDispatch::EventSource {
                source_id,
                payload: event,
                csp_violations,
            },
        )
    }

    fn evaluate_fetch_stream_event(
        &self,
        worker_id: u32,
        stream_id: u32,
        event: &serde_json::Value,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        self.evaluate_turn_with_event(
            worker_id,
            NativeWorkerDispatch::FetchStream {
                stream_id,
                payload: event,
            },
        )
    }

    fn evaluate_fetch_upload_event(
        &self,
        worker_id: u32,
        stream_id: u32,
        event: &serde_json::Value,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        self.evaluate_turn_with_event(
            worker_id,
            NativeWorkerDispatch::FetchUpload {
                stream_id,
                payload: event,
            },
        )
    }
}

/// Owns dedicated-worker realms and the bounded messages waiting for their
/// page owner. Worker execution is deliberately serialized at the page turn
/// boundary: this keeps the native backend deterministic while preserving the
/// observable message/error/termination contract.
pub(crate) struct NativeWorkerRegistry {
    workers: BTreeMap<u32, NativeDedicatedWorker>,
    shared_worker_keys: BTreeMap<String, u32>,
    next_worker_timer_id: u32,
    pending_messages: VecDeque<NativeWorkerMessage>,
    pending_message_port_messages: VecDeque<NativeMessagePortPageMessage>,
    pending_page_message_port_commands: VecDeque<NativePageMessagePortCommand>,
    pending_websocket_commands: VecDeque<NativeWorkerWebSocketCommand>,
    pending_event_source_commands: VecDeque<NativeWorkerEventSourceCommand>,
    worker_fetch_stream_connections: BTreeMap<(u32, u32), NativeFetchStreamConnection>,
    worker_fetch_upload_connections: BTreeMap<(u32, u32), NativeFetchUploadConnection>,
    stream_worker_fetches: bool,
    message_port_routes: BTreeMap<String, NativeMessagePortRoute>,
}

impl NativeWorkerRegistry {
    pub(crate) fn new() -> Self {
        Self::new_inner(false)
    }

    /// Construct a registry with worker response streams enabled. The
    /// content-process owner uses this for HTTP(S) responses and the inline
    /// owner uses it for registered fixture responses; both feed the same
    /// demand-driven transport and serialized worker event pump.
    pub(crate) fn new_with_fetch_streams() -> Self {
        Self::new_inner(true)
    }

    fn new_inner(stream_worker_fetches: bool) -> Self {
        Self {
            workers: BTreeMap::new(),
            shared_worker_keys: BTreeMap::new(),
            next_worker_timer_id: 0,
            pending_messages: VecDeque::new(),
            pending_message_port_messages: VecDeque::new(),
            pending_page_message_port_commands: VecDeque::new(),
            pending_websocket_commands: VecDeque::new(),
            pending_event_source_commands: VecDeque::new(),
            worker_fetch_stream_connections: BTreeMap::new(),
            worker_fetch_upload_connections: BTreeMap::new(),
            stream_worker_fetches,
            message_port_routes: BTreeMap::new(),
        }
    }

    fn evaluate_worker_with_loader<F>(
        &mut self,
        worker_id: u32,
        loader: &mut NativeResourceLoader,
        evaluate: F,
    ) -> Result<NativeScriptEvaluation, NativeEngineError>
    where
        F: FnOnce(&NativeDedicatedWorker) -> Result<NativeScriptEvaluation, NativeEngineError>,
    {
        let worker = self.workers.get(&worker_id).ok_or_else(|| {
            NativeEngineError::invalid("native Worker", "worker no longer exists")
        })?;
        worker.runtime.set_sync_xhr_loader(loader);
        let result = evaluate(worker);
        if let Some(updated_loader) = worker.runtime.take_sync_xhr_loader() {
            loader.merge_fetch_task_state(updated_loader)?;
        }
        result
    }

    pub(crate) fn clear(&mut self) {
        self.workers.clear();
        self.shared_worker_keys.clear();
        self.next_worker_timer_id = 0;
        self.pending_messages.clear();
        self.pending_message_port_messages.clear();
        self.pending_page_message_port_commands.clear();
        self.pending_websocket_commands.clear();
        self.pending_event_source_commands.clear();
        for (_, connection) in std::mem::take(&mut self.worker_fetch_stream_connections) {
            let _ = connection
                .commands
                .try_send(NativeFetchStreamCommand::Cancel);
        }
        for (_, connection) in std::mem::take(&mut self.worker_fetch_upload_connections) {
            let _ = connection
                .commands
                .try_send(NativeFetchUploadCommand::Cancel);
        }
        self.message_port_routes.clear();
    }

    pub(crate) fn take_messages(&mut self) -> Vec<NativeWorkerMessage> {
        self.pending_messages.drain(..).collect()
    }

    pub(crate) fn take_message_port_messages(&mut self) -> Vec<NativeMessagePortPageMessage> {
        self.pending_message_port_messages.drain(..).collect()
    }

    pub(crate) fn take_page_message_port_commands(&mut self) -> Vec<NativePageMessagePortCommand> {
        self.pending_page_message_port_commands.drain(..).collect()
    }

    pub(crate) fn take_websocket_commands(&mut self) -> Vec<NativeWorkerWebSocketCommand> {
        self.pending_websocket_commands.drain(..).collect()
    }

    pub(crate) fn take_event_source_commands(&mut self) -> Vec<NativeWorkerEventSourceCommand> {
        self.pending_event_source_commands.drain(..).collect()
    }

    /// Run one due timer turn for the next worker that has work ready. Worker
    /// callbacks stay inside their isolated realm and can only emit the
    /// bounded worker message/lifecycle/fetch commands. A rotating cursor
    /// prevents the lowest worker id from monopolizing each page boundary.
    pub(crate) async fn run_due_timers(
        &mut self,
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        let worker_ids = self.workers.keys().copied().collect::<Vec<_>>();
        let mut selected_worker_id = None;
        let after_cursor = worker_ids
            .iter()
            .copied()
            .filter(|worker_id| *worker_id > self.next_worker_timer_id);
        let before_cursor = worker_ids
            .iter()
            .copied()
            .filter(|worker_id| *worker_id <= self.next_worker_timer_id);
        for worker_id in after_cursor.chain(before_cursor) {
            let Some(worker) = self.workers.get(&worker_id) else {
                continue;
            };
            if worker
                .runtime
                .next_worker_timer_delay_ms()?
                .is_some_and(|delay| delay == 0)
            {
                selected_worker_id = Some(worker_id);
                break;
            }
        }
        let Some(worker_id) = selected_worker_id else {
            return Ok(());
        };
        self.next_worker_timer_id = worker_id;
        let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
            worker.evaluate_turn(
                worker_id,
                "globalThis.__glassRunWorkerTimers(performance.now());",
            )
        });
        match evaluation {
            Ok(evaluation) => {
                self.collect_worker_evaluation(worker_id, evaluation, loader)
                    .await?
            }
            Err(error) => {
                let worker_url = self
                    .workers
                    .get(&worker_id)
                    .map(|worker| worker.url.clone())
                    .unwrap_or_default();
                self.workers.remove(&worker_id);
                self.remove_worker_routes(worker_id);
                self.queue_error(worker_id, &worker_url, &error.to_string())?;
            }
        }
        Ok(())
    }

    pub(crate) async fn apply_commands(
        &mut self,
        commands: Vec<NativeScriptCommand>,
        loader: &mut NativeResourceLoader,
        owner_url: &str,
    ) -> Result<(), NativeEngineError> {
        if commands.len() > MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native Worker commands",
                MAX_NATIVE_WORKER_MESSAGES,
                commands.len(),
            ));
        }
        for command in commands {
            match command {
                NativeScriptCommand::SharedWorkerCreate {
                    connection_id,
                    href,
                    name,
                    worker_type,
                    transfer_port,
                } => {
                    self.create_shared_worker(
                        connection_id,
                        href,
                        name,
                        worker_type,
                        transfer_port,
                        loader,
                        owner_url,
                    )
                    .await?;
                }
                NativeScriptCommand::WorkerCreate {
                    worker_id,
                    href,
                    worker_type,
                } => {
                    self.create_worker(worker_id, href, worker_type, loader, owner_url)
                        .await?;
                }
                NativeScriptCommand::WorkerPostMessage {
                    worker_id,
                    data,
                    transfer_ports,
                    object_urls,
                } => {
                    self.post_message(worker_id, data, transfer_ports, object_urls, loader)
                        .await?;
                }
                NativeScriptCommand::WorkerTerminate { worker_id }
                | NativeScriptCommand::WorkerClose { worker_id } => {
                    self.workers.remove(&worker_id);
                    self.remove_worker_routes(worker_id);
                }
                _ => {
                    return Err(NativeEngineError::invalid(
                        "native Worker command",
                        "command was not routed through the Worker host boundary",
                    ));
                }
            }
        }
        Ok(())
    }

    async fn create_worker(
        &mut self,
        worker_id: u32,
        href: String,
        worker_type: String,
        loader: &mut NativeResourceLoader,
        owner_url: &str,
    ) -> Result<(), NativeEngineError> {
        if worker_id == 0 {
            return Err(NativeEngineError::invalid(
                "native Worker id",
                "must be positive",
            ));
        }
        if self.workers.len() >= MAX_NATIVE_WORKERS {
            return Err(NativeEngineError::limit(
                "native Workers",
                MAX_NATIVE_WORKERS,
                self.workers.len().saturating_add(1),
            ));
        }
        if self.workers.contains_key(&worker_id) {
            return Err(NativeEngineError::invalid(
                "native Worker id",
                "must be unique within the page realm",
            ));
        }
        validate_url_text("native Worker URL", &href)?;
        let is_module = worker_type.eq_ignore_ascii_case("module");
        if !worker_type.is_empty() && !worker_type.eq_ignore_ascii_case("classic") && !is_module {
            return Err(NativeEngineError::UnsupportedUrl {
                reason: "native Worker type must be classic or module".into(),
            });
        }

        let resource = match loader
            .load_worker_async(owner_url, &href, MAX_NATIVE_SCRIPT_BYTES)
            .await
        {
            Ok(Some(resource)) => resource,
            Ok(None) => {
                self.queue_error(worker_id, &href, "worker script was blocked or unavailable")?;
                return Ok(());
            }
            Err(error) => {
                self.queue_error(worker_id, &href, &error.to_string())?;
                return Ok(());
            }
        };
        let (source, import_script_counts, module_sources) = if is_module {
            let module_sources = self
                .load_worker_module_graph(loader, owner_url, resource.clone())
                .await?;
            (resource.body.clone(), BTreeMap::new(), module_sources)
        } else {
            let (source, import_script_counts) = self
                .load_worker_script_graph(loader, resource.clone())
                .await?;
            (source, import_script_counts, BTreeMap::new())
        };
        let runtime =
            match NativeJavaScriptRuntime::new_with_context_id(format!("glass-worker-{worker_id}"))
            {
                Ok(runtime) => runtime,
                Err(error) => {
                    self.queue_error(worker_id, &resource.url, &error.to_string())?;
                    return Ok(());
                }
            };
        self.workers.insert(
            worker_id,
            NativeDedicatedWorker {
                url: resource.url.clone(),
                import_script_counts,
                module_sources,
                is_module,
                is_shared: false,
                next_module_turn: AtomicU64::new(1),
                runtime,
            },
        );
        let evaluation = {
            self.evaluate_worker_with_loader(worker_id, loader, |worker| {
                worker.evaluate_initial(worker_id, &source)
            })
        };
        match evaluation {
            Ok(evaluation) => {
                self.collect_worker_evaluation(worker_id, evaluation, loader)
                    .await
            }
            Err(error) => {
                self.workers.remove(&worker_id);
                self.remove_worker_routes(worker_id);
                self.queue_error(worker_id, &resource.url, &error.to_string())
            }
        }
    }

    async fn create_shared_worker(
        &mut self,
        connection_id: u32,
        href: String,
        name: String,
        worker_type: String,
        transfer_port: NativeMessagePortTransfer,
        loader: &mut NativeResourceLoader,
        owner_url: &str,
    ) -> Result<(), NativeEngineError> {
        if connection_id == 0 {
            return Err(NativeEngineError::invalid(
                "native SharedWorker connection id",
                "must be positive",
            ));
        }
        validate_url_text("native SharedWorker URL", &href)?;
        if name.len() > MAX_NATIVE_SHARED_WORKER_NAME_BYTES {
            return Err(NativeEngineError::limit(
                "native SharedWorker name",
                MAX_NATIVE_SHARED_WORKER_NAME_BYTES,
                name.len(),
            ));
        }
        if name.bytes().any(|byte| byte < 0x20 || byte == 0x7f) {
            return Err(NativeEngineError::invalid(
                "native SharedWorker name",
                "must not contain control characters",
            ));
        }
        let is_module = worker_type.eq_ignore_ascii_case("module");
        if !worker_type.is_empty() && !worker_type.eq_ignore_ascii_case("classic") && !is_module {
            return Err(NativeEngineError::UnsupportedUrl {
                reason: "native SharedWorker type must be classic or module".into(),
            });
        }
        validate_message_port_transfers(std::slice::from_ref(&transfer_port))?;
        let shared_key = format!("{href}\u{0}{name}\u{0}{worker_type}");
        if let Some(worker_id) = self.shared_worker_keys.get(&shared_key).copied() {
            if self.workers.contains_key(&worker_id) {
                let worker_url = self
                    .workers
                    .get(&worker_id)
                    .map(|worker| worker.url.clone())
                    .expect("SharedWorker key points to a worker");
                self.register_page_transfers(worker_id, std::slice::from_ref(&transfer_port))?;
                let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
                    worker.evaluate_shared_connect(worker_id, &transfer_port)
                });
                match evaluation {
                    Ok(evaluation) => {
                        if let Err(error) = self
                            .collect_worker_evaluation(worker_id, evaluation, loader)
                            .await
                        {
                            self.remove_transfer_routes(std::slice::from_ref(&transfer_port));
                            return Err(error);
                        }
                    }
                    Err(error) => {
                        self.remove_transfer_routes(std::slice::from_ref(&transfer_port));
                        self.workers.remove(&worker_id);
                        self.remove_worker_routes(worker_id);
                        self.queue_error(connection_id, &worker_url, &error.to_string())?;
                    }
                }
                return Ok(());
            }
            self.shared_worker_keys.remove(&shared_key);
        }
        if self.workers.len() >= MAX_NATIVE_WORKERS {
            return Err(NativeEngineError::limit(
                "native workers",
                MAX_NATIVE_WORKERS,
                self.workers.len().saturating_add(1),
            ));
        }
        if self.workers.contains_key(&connection_id) {
            return Err(NativeEngineError::invalid(
                "native SharedWorker connection id",
                "must be unique within the page realm",
            ));
        }
        let resource = match loader
            .load_worker_async(owner_url, &href, MAX_NATIVE_SCRIPT_BYTES)
            .await
        {
            Ok(Some(resource)) => resource,
            Ok(None) => {
                self.queue_error(
                    connection_id,
                    &href,
                    "SharedWorker script was blocked or unavailable",
                )?;
                return Ok(());
            }
            Err(error) => {
                self.queue_error(connection_id, &href, &error.to_string())?;
                return Ok(());
            }
        };
        let (source, import_script_counts, module_sources) = if is_module {
            let module_sources = self
                .load_worker_module_graph(loader, owner_url, resource.clone())
                .await?;
            (resource.body.clone(), BTreeMap::new(), module_sources)
        } else {
            let (source, import_script_counts) = self
                .load_worker_script_graph(loader, resource.clone())
                .await?;
            (source, import_script_counts, BTreeMap::new())
        };
        let runtime = match NativeJavaScriptRuntime::new_with_context_id(format!(
            "glass-shared-worker-{connection_id}"
        )) {
            Ok(runtime) => runtime,
            Err(error) => {
                self.queue_error(connection_id, &resource.url, &error.to_string())?;
                return Ok(());
            }
        };
        self.workers.insert(
            connection_id,
            NativeDedicatedWorker {
                url: resource.url.clone(),
                import_script_counts,
                module_sources,
                is_module,
                is_shared: true,
                next_module_turn: AtomicU64::new(1),
                runtime,
            },
        );
        self.shared_worker_keys
            .insert(shared_key.clone(), connection_id);
        if let Err(error) =
            self.register_page_transfers(connection_id, std::slice::from_ref(&transfer_port))
        {
            self.workers.remove(&connection_id);
            self.shared_worker_keys.remove(&shared_key);
            return Err(error);
        }
        let initial = self.evaluate_worker_with_loader(connection_id, loader, |worker| {
            worker.evaluate_initial(connection_id, &source)
        });
        match initial {
            Ok(evaluation) => {
                if let Err(error) = self
                    .collect_worker_evaluation(connection_id, evaluation, loader)
                    .await
                {
                    self.workers.remove(&connection_id);
                    self.remove_worker_routes(connection_id);
                    return Err(error);
                }
            }
            Err(error) => {
                self.workers.remove(&connection_id);
                self.remove_worker_routes(connection_id);
                self.queue_error(connection_id, &resource.url, &error.to_string())?;
                return Ok(());
            }
        }
        let connect = self.evaluate_worker_with_loader(connection_id, loader, |worker| {
            worker.evaluate_shared_connect(connection_id, &transfer_port)
        });
        match connect {
            Ok(evaluation) => {
                if let Err(error) = self
                    .collect_worker_evaluation(connection_id, evaluation, loader)
                    .await
                {
                    self.workers.remove(&connection_id);
                    self.remove_worker_routes(connection_id);
                    return Err(error);
                }
            }
            Err(error) => {
                self.remove_transfer_routes(std::slice::from_ref(&transfer_port));
                self.workers.remove(&connection_id);
                self.remove_worker_routes(connection_id);
                self.queue_error(connection_id, &resource.url, &error.to_string())?;
            }
        }
        Ok(())
    }

    async fn post_message(
        &mut self,
        worker_id: u32,
        data: serde_json::Value,
        transfer_ports: Vec<NativeMessagePortTransfer>,
        object_urls: Vec<NativeObjectUrlTransfer>,
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        if !self.workers.contains_key(&worker_id) {
            return Ok(());
        }
        self.register_page_transfers(worker_id, &transfer_ports)?;
        validate_native_object_url_transfers(&object_urls)?;
        validate_native_message_payload(
            &serde_json::json!({
                "data": &data,
                "transfer_ports": &transfer_ports,
                "object_urls": &object_urls,
            }),
            "native Worker message",
        )?;
        let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
            worker.runtime.install_object_url_transfers(&object_urls)?;
            worker.evaluate_turn_with_event(
                worker_id,
                NativeWorkerDispatch::Message {
                    data: &data,
                    transfer_ports: &transfer_ports,
                    object_urls: &object_urls,
                },
            )
        });
        match evaluation {
            Ok(evaluation) => {
                self.collect_worker_evaluation(worker_id, evaluation, loader)
                    .await
            }
            Err(error) => {
                self.workers.remove(&worker_id);
                self.remove_worker_routes(worker_id);
                self.queue_error(worker_id, "", &error.to_string())
            }
        }
    }

    async fn collect_worker_evaluation(
        &mut self,
        worker_id: u32,
        evaluation: NativeScriptEvaluation,
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        let mut evaluations = VecDeque::from([(worker_id, evaluation)]);
        let mut evaluation_count = 0usize;
        while let Some((current_worker_id, evaluation)) = evaluations.pop_front() {
            evaluation_count = evaluation_count.saturating_add(1);
            if evaluation_count > MAX_NATIVE_WORKER_MESSAGES {
                return Err(NativeEngineError::limit(
                    "native Worker event-loop turns",
                    MAX_NATIVE_WORKER_MESSAGES,
                    evaluation_count,
                ));
            }
            let mut closed = false;
            let message_port_commands = self
                .workers
                .get(&current_worker_id)
                .map(|worker| worker.runtime.take_message_port_commands())
                .unwrap_or_default();
            for command in message_port_commands {
                match command {
                    NativeScriptCommand::MessagePortPostMessage {
                        bridge_key,
                        data,
                        worker_id: Some(command_worker_id),
                        transfer_ports,
                        object_urls,
                    } if command_worker_id == current_worker_id => {
                        self.queue_page_message_port(
                            current_worker_id,
                            bridge_key,
                            data,
                            transfer_ports,
                            object_urls,
                        )?;
                    }
                    _ => {
                        return Err(NativeEngineError::invalid(
                            "native Worker MessagePort command",
                            "worker emitted an invalid MessagePort host command",
                        ));
                    }
                }
            }
            for command in evaluation.commands {
                match command {
                    NativeScriptCommand::WorkerPostMessage {
                        worker_id: command_worker_id,
                        data,
                        transfer_ports,
                        object_urls,
                    } if command_worker_id == current_worker_id => {
                        self.register_worker_transfers(current_worker_id, &transfer_ports)?;
                        self.queue_message(NativeWorkerMessage {
                            worker_id: current_worker_id,
                            data,
                            error: None,
                            transfer_ports,
                            object_urls,
                        })?;
                    }
                    NativeScriptCommand::WorkerClose {
                        worker_id: command_worker_id,
                    } if command_worker_id == current_worker_id => closed = true,
                    NativeScriptCommand::MessagePortPostMessage {
                        bridge_key,
                        data,
                        worker_id: Some(command_worker_id),
                        transfer_ports,
                        object_urls,
                    } if command_worker_id == current_worker_id => {
                        self.queue_page_message_port(
                            current_worker_id,
                            bridge_key,
                            data,
                            transfer_ports,
                            object_urls,
                        )?;
                    }
                    NativeScriptCommand::Fetch {
                        worker_id: Some(command_worker_id),
                        ..
                    } if command_worker_id == current_worker_id => {
                        let resolved = self
                            .resolve_worker_fetch(current_worker_id, command, loader)
                            .await?;
                        evaluations.push_back((current_worker_id, resolved));
                    }
                    NativeScriptCommand::FetchStreamRead {
                        stream_id,
                        worker_id: Some(command_worker_id),
                    } if command_worker_id == current_worker_id => {
                        self.process_worker_fetch_stream_command(
                            current_worker_id,
                            NativeScriptCommand::FetchStreamRead {
                                stream_id,
                                worker_id: Some(command_worker_id),
                            },
                        )?;
                    }
                    NativeScriptCommand::FetchStreamCancel {
                        stream_id,
                        worker_id: Some(command_worker_id),
                    } if command_worker_id == current_worker_id => {
                        self.process_worker_fetch_stream_command(
                            current_worker_id,
                            NativeScriptCommand::FetchStreamCancel {
                                stream_id,
                                worker_id: Some(command_worker_id),
                            },
                        )?;
                    }
                    command @ NativeScriptCommand::FetchUploadChunk {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::FetchUploadEnd {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::FetchUploadError {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::FetchUploadCancel {
                        worker_id: Some(command_worker_id),
                        ..
                    } if command_worker_id == current_worker_id => {
                        self.process_worker_fetch_upload_command(current_worker_id, command)?;
                    }
                    command @ NativeScriptCommand::WebSocketOpen {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::WebSocketSend {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::WebSocketClose {
                        worker_id: Some(command_worker_id),
                        ..
                    } if command_worker_id == current_worker_id => {
                        self.queue_websocket_command(current_worker_id, command)?;
                    }
                    command @ NativeScriptCommand::EventSourceOpen {
                        worker_id: Some(command_worker_id),
                        ..
                    }
                    | command @ NativeScriptCommand::EventSourceClose {
                        worker_id: Some(command_worker_id),
                        ..
                    } if command_worker_id == current_worker_id => {
                        self.queue_event_source_command(current_worker_id, command)?;
                    }
                    _ => {
                        return Err(NativeEngineError::invalid(
                            "native Worker command",
                            "worker emitted an invalid host command",
                        ));
                    }
                }
            }
            if closed {
                self.workers.remove(&current_worker_id);
                self.remove_worker_routes(current_worker_id);
            }
        }
        Ok(())
    }

    /// Route page-owned MessagePort commands into the worker endpoint named by
    /// the bridge key. Commands are applied after ordinary WorkerCreate and
    /// WorkerPostMessage commands from the same page turn, so a page can wire
    /// a channel and immediately send its first message deterministically.
    pub(crate) async fn apply_page_message_port_commands(
        &mut self,
        commands: Vec<NativeScriptCommand>,
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        if commands.len() > MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native page MessagePort commands",
                MAX_NATIVE_WORKER_MESSAGES,
                commands.len(),
            ));
        }
        for command in commands {
            let NativeScriptCommand::MessagePortPostMessage {
                bridge_key,
                data,
                worker_id: None,
                transfer_ports,
                object_urls,
            } = command
            else {
                return Err(NativeEngineError::invalid(
                    "native page MessagePort command",
                    "command did not originate from the page realm",
                ));
            };
            let Some(route) = self.message_port_routes.get(&bridge_key).cloned() else {
                let command = NativePageMessagePortCommand {
                    bridge_key,
                    data,
                    transfer_ports,
                    object_urls,
                    source_context_id: String::new(),
                    source_frame_id: String::new(),
                };
                validate_page_message_port_command(&command)?;
                if self.pending_page_message_port_commands.len() >= MAX_NATIVE_WORKER_MESSAGES {
                    return Err(NativeEngineError::limit(
                        "native pending page MessagePort commands",
                        MAX_NATIVE_WORKER_MESSAGES,
                        self.pending_page_message_port_commands
                            .len()
                            .saturating_add(1),
                    ));
                }
                self.pending_page_message_port_commands.push_back(command);
                continue;
            };
            self.register_page_transfers(route.worker_id, &transfer_ports)?;
            validate_native_object_url_transfers(&object_urls)?;
            validate_native_message_payload(
                &serde_json::json!({
                    "data": &data,
                    "transfer_ports": &transfer_ports,
                    "object_urls": &object_urls,
                }),
                "native page MessagePort event",
            )?;
            let worker_id = route.worker_id;
            let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
                worker.evaluate_turn_with_event(
                    worker_id,
                    NativeWorkerDispatch::MessagePort {
                        bridge_key: &bridge_key,
                        data: &data,
                        transfer_ports: &transfer_ports,
                        object_urls: &object_urls,
                    },
                )
            });
            match evaluation {
                Ok(evaluation) => {
                    self.collect_worker_evaluation(worker_id, evaluation, loader)
                        .await?;
                }
                Err(error) => {
                    let worker_url = self
                        .workers
                        .get(&worker_id)
                        .map(|worker| worker.url.clone())
                        .unwrap_or_default();
                    self.workers.remove(&worker_id);
                    self.remove_worker_routes(worker_id);
                    self.queue_error(worker_id, &worker_url, &error.to_string())?;
                }
            }
        }
        Ok(())
    }

    fn register_page_transfers(
        &mut self,
        worker_id: u32,
        transfers: &[NativeMessagePortTransfer],
    ) -> Result<(), NativeEngineError> {
        self.register_transfers(worker_id, transfers)
    }

    fn register_worker_transfers(
        &mut self,
        worker_id: u32,
        transfers: &[NativeMessagePortTransfer],
    ) -> Result<(), NativeEngineError> {
        self.register_transfers(worker_id, transfers)
    }

    fn register_transfers(
        &mut self,
        worker_id: u32,
        transfers: &[NativeMessagePortTransfer],
    ) -> Result<(), NativeEngineError> {
        if transfers.len() > MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native MessagePort transfers",
                MAX_NATIVE_WORKER_MESSAGES,
                transfers.len(),
            ));
        }
        for transfer in transfers {
            validate_message_port_transfers(std::slice::from_ref(transfer))?;
            if self.message_port_routes.contains_key(&transfer.bridge_key) {
                return Err(NativeEngineError::invalid(
                    "native MessagePort transfer",
                    "bridge key was already transferred",
                ));
            }
            self.message_port_routes.insert(
                transfer.bridge_key.clone(),
                NativeMessagePortRoute { worker_id },
            );
        }
        Ok(())
    }

    fn remove_transfer_routes(&mut self, transfers: &[NativeMessagePortTransfer]) {
        for transfer in transfers {
            self.message_port_routes.remove(&transfer.bridge_key);
        }
        let live_bridge_keys = self
            .message_port_routes
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        self.pending_message_port_messages
            .retain(|message| live_bridge_keys.contains(&message.bridge_key));
    }

    fn queue_page_message_port(
        &mut self,
        worker_id: u32,
        bridge_key: String,
        data: serde_json::Value,
        transfer_ports: Vec<NativeMessagePortTransfer>,
        object_urls: Vec<NativeObjectUrlTransfer>,
    ) -> Result<(), NativeEngineError> {
        let Some(route) = self.message_port_routes.get(&bridge_key).cloned() else {
            return Ok(());
        };
        if route.worker_id != worker_id {
            return Err(NativeEngineError::invalid(
                "native MessagePort route",
                "worker id does not own the MessagePort bridge",
            ));
        }
        self.register_worker_transfers(worker_id, &transfer_ports)?;
        validate_native_object_url_transfers(&object_urls)?;
        validate_native_message_payload(
            &serde_json::json!({
                "data": &data,
                "transfer_ports": &transfer_ports,
                "object_urls": &object_urls,
            }),
            "native page MessagePort event",
        )?;
        if self.pending_message_port_messages.len() >= MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native page MessagePort messages",
                MAX_NATIVE_WORKER_MESSAGES,
                self.pending_message_port_messages.len().saturating_add(1),
            ));
        }
        self.pending_message_port_messages
            .push_back(NativeMessagePortPageMessage {
                bridge_key,
                data,
                transfer_ports,
                object_urls,
            });
        Ok(())
    }

    fn remove_worker_routes(&mut self, worker_id: u32) {
        let stream_keys = self
            .worker_fetch_stream_connections
            .keys()
            .copied()
            .filter(|(stream_worker_id, _)| *stream_worker_id == worker_id)
            .collect::<Vec<_>>();
        for stream_key in stream_keys {
            if let Some(connection) = self.worker_fetch_stream_connections.remove(&stream_key) {
                let _ = connection
                    .commands
                    .try_send(NativeFetchStreamCommand::Cancel);
            }
        }
        let upload_keys = self
            .worker_fetch_upload_connections
            .keys()
            .copied()
            .filter(|(upload_worker_id, _)| *upload_worker_id == worker_id)
            .collect::<Vec<_>>();
        for upload_key in upload_keys {
            if let Some(connection) = self.worker_fetch_upload_connections.remove(&upload_key) {
                let _ = connection
                    .commands
                    .try_send(NativeFetchUploadCommand::Cancel);
            }
        }
        self.message_port_routes
            .retain(|_, route| route.worker_id != worker_id);
        self.shared_worker_keys
            .retain(|_, shared_worker_id| *shared_worker_id != worker_id);
        let live_bridge_keys = self
            .message_port_routes
            .keys()
            .cloned()
            .collect::<BTreeSet<_>>();
        self.pending_message_port_messages
            .retain(|message| live_bridge_keys.contains(&message.bridge_key));
    }

    pub(crate) async fn dispatch_websocket_event(
        &mut self,
        worker_id: u32,
        socket_id: u32,
        event: &serde_json::Value,
        csp_violations: &[NativeCspViolation],
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        if !self.workers.contains_key(&worker_id) {
            return Ok(());
        }
        let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
            worker.evaluate_websocket_event(worker_id, socket_id, event, csp_violations)
        });
        match evaluation {
            Ok(evaluation) => {
                self.collect_worker_evaluation(worker_id, evaluation, loader)
                    .await
            }
            Err(error) => {
                let worker_url = self
                    .workers
                    .get(&worker_id)
                    .map(|worker| worker.url.clone())
                    .unwrap_or_default();
                self.workers.remove(&worker_id);
                self.remove_worker_routes(worker_id);
                self.queue_error(worker_id, &worker_url, &error.to_string())
            }
        }
    }

    pub(crate) async fn dispatch_event_source_event(
        &mut self,
        worker_id: u32,
        source_id: u32,
        event: &serde_json::Value,
        csp_violations: &[NativeCspViolation],
        loader: &mut NativeResourceLoader,
    ) -> Result<(), NativeEngineError> {
        if !self.workers.contains_key(&worker_id) {
            return Ok(());
        }
        let evaluation = self.evaluate_worker_with_loader(worker_id, loader, |worker| {
            worker.evaluate_event_source_event(worker_id, source_id, event, csp_violations)
        });
        match evaluation {
            Ok(evaluation) => {
                self.collect_worker_evaluation(worker_id, evaluation, loader)
                    .await
            }
            Err(error) => {
                let worker_url = self
                    .workers
                    .get(&worker_id)
                    .map(|worker| worker.url.clone())
                    .unwrap_or_default();
                self.workers.remove(&worker_id);
                self.remove_worker_routes(worker_id);
                self.queue_error(worker_id, &worker_url, &error.to_string())
            }
        }
    }

    /// Deliver one host-owned worker Fetch response-stream event into its
    /// persistent worker realm. Worker stream reads and cancellation commands
    /// are collected by the same serialized owner as ordinary worker fetches.
    pub(crate) async fn pump_fetch_stream_event(
        &mut self,
        loader: &mut NativeResourceLoader,
    ) -> Result<bool, NativeEngineError> {
        let stream_keys = self
            .worker_fetch_stream_connections
            .keys()
            .copied()
            .collect::<Vec<_>>();
        for stream_key @ (worker_id, stream_id) in stream_keys {
            let event = {
                let Some(connection) = self.worker_fetch_stream_connections.get_mut(&stream_key)
                else {
                    continue;
                };
                match connection.events.try_recv() {
                    Ok(event) => {
                        connection.read_pending = false;
                        Some(event)
                    }
                    Err(tokio::sync::mpsc::error::TryRecvError::Empty) => None,
                    Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => {
                        self.worker_fetch_stream_connections.remove(&stream_key);
                        None
                    }
                }
            };
            let Some(event) = event else {
                continue;
            };
            let remove_after_dispatch = matches!(
                &event,
                NativeFetchStreamEvent::End | NativeFetchStreamEvent::Error { .. }
            );
            let payload = worker_fetch_stream_event_payload(&event);
            let evaluation = if self.workers.contains_key(&worker_id) {
                Some(
                    self.evaluate_worker_with_loader(worker_id, loader, |worker| {
                        worker.evaluate_fetch_stream_event(worker_id, stream_id, &payload)
                    }),
                )
            } else {
                None
            };
            match evaluation {
                Some(Ok(evaluation)) => {
                    self.collect_worker_evaluation(worker_id, evaluation, loader)
                        .await?;
                }
                Some(Err(error)) => {
                    let worker_url = self
                        .workers
                        .get(&worker_id)
                        .map(|worker| worker.url.clone())
                        .unwrap_or_default();
                    self.workers.remove(&worker_id);
                    self.remove_worker_routes(worker_id);
                    self.queue_error(worker_id, &worker_url, &error.to_string())?;
                }
                None => {
                    if let Some(connection) =
                        self.worker_fetch_stream_connections.remove(&stream_key)
                    {
                        let _ = connection
                            .commands
                            .try_send(NativeFetchStreamCommand::Cancel);
                    }
                }
            }
            if remove_after_dispatch
                && let Some(connection) = self.worker_fetch_stream_connections.remove(&stream_key)
            {
                let _ = connection
                    .commands
                    .try_send(NativeFetchStreamCommand::Cancel);
            }
            return Ok(true);
        }
        Ok(false)
    }

    pub(crate) async fn pump_fetch_stream_events(
        &mut self,
        loader: &mut NativeResourceLoader,
    ) -> Result<usize, NativeEngineError> {
        let mut pumped = 0usize;
        for _ in 0..MAX_NATIVE_WORKER_MESSAGES {
            if !self.pump_fetch_stream_event(loader).await? {
                break;
            }
            pumped = pumped.saturating_add(1);
            tokio::task::yield_now().await;
        }
        Ok(pumped)
    }

    fn process_worker_fetch_stream_command(
        &mut self,
        worker_id: u32,
        command: NativeScriptCommand,
    ) -> Result<(), NativeEngineError> {
        match command {
            NativeScriptCommand::FetchStreamRead {
                stream_id,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                let stream_key = (worker_id, stream_id);
                let connection = self
                    .worker_fetch_stream_connections
                    .get_mut(&stream_key)
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "worker fetch response stream read".into(),
                        reason: "worker fetch response stream identifier is not active".into(),
                    })?;
                if connection.read_pending {
                    return Err(NativeEngineError::Network {
                        operation: "worker fetch response stream read".into(),
                        reason: "worker fetch response stream already has a pending read".into(),
                    });
                }
                connection.read_pending = true;
                connection
                    .commands
                    .try_send(NativeFetchStreamCommand::Read)
                    .map_err(|_| NativeEngineError::Network {
                        operation: "worker fetch response stream read".into(),
                        reason: "worker fetch response stream task is unavailable".into(),
                    })?;
                Ok(())
            }
            NativeScriptCommand::FetchStreamCancel {
                stream_id,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                if let Some(connection) = self
                    .worker_fetch_stream_connections
                    .remove(&(worker_id, stream_id))
                {
                    let _ = connection
                        .commands
                        .try_send(NativeFetchStreamCommand::Cancel);
                }
                Ok(())
            }
            _ => Err(NativeEngineError::invalid(
                "native Worker fetch response stream command",
                "worker id does not match the owning worker",
            )),
        }
    }

    fn process_worker_fetch_upload_command(
        &mut self,
        worker_id: u32,
        command: NativeScriptCommand,
    ) -> Result<(), NativeEngineError> {
        match command {
            NativeScriptCommand::FetchUploadChunk {
                stream_id,
                data_base64,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                let upload_key = (worker_id, stream_id);
                let connection = self
                    .worker_fetch_upload_connections
                    .get_mut(&upload_key)
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "Worker fetch request upload chunk".into(),
                        reason: "Worker fetch request upload identifier is not active".into(),
                    })?;
                if !connection.demand_pending {
                    return Err(NativeEngineError::Network {
                        operation: "Worker fetch request upload chunk".into(),
                        reason: "Worker fetch request upload chunk arrived without demand".into(),
                    });
                }
                let data = base64::engine::general_purpose::STANDARD
                    .decode(data_base64)
                    .map_err(|_| {
                        NativeEngineError::invalid(
                            "Worker fetch request upload chunk",
                            "must be valid base64",
                        )
                    })?;
                let next_total = connection.total_bytes.saturating_add(data.len());
                let next_chunks = connection.chunk_count.saturating_add(1);
                if next_total > MAX_NATIVE_FORM_BODY_BYTES
                    || next_chunks > MAX_NATIVE_FETCH_UPLOAD_CHUNKS
                {
                    let connection = self
                        .worker_fetch_upload_connections
                        .remove(&upload_key)
                        .expect("Worker fetch upload connection was checked above");
                    let message = if next_total > MAX_NATIVE_FORM_BODY_BYTES {
                        "native Worker fetch request upload body exceeds its limit"
                    } else {
                        "native Worker fetch request upload chunk limit exceeded"
                    };
                    let _ = connection
                        .commands
                        .try_send(NativeFetchUploadCommand::Error {
                            message: message.into(),
                        });
                    return Ok(());
                }
                let connection = self
                    .worker_fetch_upload_connections
                    .get_mut(&upload_key)
                    .expect("Worker fetch upload connection was checked above");
                connection.total_bytes = next_total;
                connection.chunk_count = next_chunks;
                connection.demand_pending = false;
                connection
                    .commands
                    .try_send(NativeFetchUploadCommand::Chunk { data })
                    .map_err(|_| NativeEngineError::Network {
                        operation: "Worker fetch request upload chunk".into(),
                        reason: "Worker fetch request upload task is unavailable".into(),
                    })?;
                Ok(())
            }
            NativeScriptCommand::FetchUploadEnd {
                stream_id,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                let upload_key = (worker_id, stream_id);
                let mut connection = self
                    .worker_fetch_upload_connections
                    .remove(&upload_key)
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "Worker fetch request upload end".into(),
                        reason: "Worker fetch request upload identifier is not active".into(),
                    })?;
                if !connection.demand_pending {
                    return Err(NativeEngineError::Network {
                        operation: "Worker fetch request upload end".into(),
                        reason: "Worker fetch request upload ended without demand".into(),
                    });
                }
                connection.demand_pending = false;
                connection
                    .commands
                    .try_send(NativeFetchUploadCommand::End)
                    .map_err(|_| NativeEngineError::Network {
                        operation: "Worker fetch request upload end".into(),
                        reason: "Worker fetch request upload task is unavailable".into(),
                    })?;
                Ok(())
            }
            NativeScriptCommand::FetchUploadError {
                stream_id,
                message,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                let connection = self
                    .worker_fetch_upload_connections
                    .remove(&(worker_id, stream_id))
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "Worker fetch request upload error".into(),
                        reason: "Worker fetch request upload identifier is not active".into(),
                    })?;
                let message = message
                    .chars()
                    .take(crate::browser_backend::MAX_TEXT_BYTES)
                    .collect();
                let _ = connection
                    .commands
                    .try_send(NativeFetchUploadCommand::Error { message });
                Ok(())
            }
            NativeScriptCommand::FetchUploadCancel {
                stream_id,
                worker_id: Some(command_worker_id),
            } if command_worker_id == worker_id => {
                if let Some(connection) = self
                    .worker_fetch_upload_connections
                    .remove(&(worker_id, stream_id))
                {
                    let _ = connection
                        .commands
                        .try_send(NativeFetchUploadCommand::Cancel);
                }
                Ok(())
            }
            _ => Err(NativeEngineError::invalid(
                "native Worker fetch request upload command",
                "worker id does not match the owning worker",
            )),
        }
    }

    fn queue_websocket_command(
        &mut self,
        worker_id: u32,
        command: NativeScriptCommand,
    ) -> Result<(), NativeEngineError> {
        let worker_url = self
            .workers
            .get(&worker_id)
            .map(|worker| worker.url.clone())
            .ok_or_else(|| {
                NativeEngineError::invalid(
                    "native Worker WebSocket command",
                    "worker no longer exists",
                )
            })?;
        if self.pending_websocket_commands.len() >= MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native Worker WebSocket commands",
                MAX_NATIVE_WORKER_MESSAGES,
                self.pending_websocket_commands.len().saturating_add(1),
            ));
        }
        self.pending_websocket_commands
            .push_back(NativeWorkerWebSocketCommand {
                worker_id,
                worker_url,
                command,
            });
        Ok(())
    }

    fn queue_event_source_command(
        &mut self,
        worker_id: u32,
        command: NativeScriptCommand,
    ) -> Result<(), NativeEngineError> {
        let worker_url = self
            .workers
            .get(&worker_id)
            .map(|worker| worker.url.clone())
            .ok_or_else(|| {
                NativeEngineError::invalid(
                    "native Worker EventSource command",
                    "worker no longer exists",
                )
            })?;
        if self.pending_event_source_commands.len() >= MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native Worker EventSource commands",
                MAX_NATIVE_WORKER_MESSAGES,
                self.pending_event_source_commands.len().saturating_add(1),
            ));
        }
        self.pending_event_source_commands
            .push_back(NativeWorkerEventSourceCommand {
                worker_id,
                worker_url,
                command,
            });
        Ok(())
    }

    fn cancel_worker_fetch_upload_connection(&mut self, upload_key: (u32, u32)) {
        if let Some(connection) = self.worker_fetch_upload_connections.remove(&upload_key) {
            let _ = connection
                .commands
                .try_send(NativeFetchUploadCommand::Cancel);
        }
    }

    /// Drive a worker-owned request-body task until it completes. The worker
    /// realm remains the sole producer: every body read is admitted by one
    /// demand event, then routed back through the normal serialized worker
    /// evaluation. HTTP and fixture owners share this loop so their
    /// cancellation and teardown behavior cannot drift.
    async fn drive_worker_fetch_upload_task<T>(
        &mut self,
        worker_id: u32,
        request_id: u32,
        task: tokio::task::JoinHandle<T>,
        loader: &mut NativeResourceLoader,
        task_operation: &str,
    ) -> Result<T, NativeEngineError>
    where
        T: Send + 'static,
    {
        loop {
            if task.is_finished() {
                return task.await.map_err(|_| {
                    NativeEngineError::worker_failure(
                        task_operation,
                        NativeWorkerFailureKind::Transport,
                        "native Worker fetch request upload task terminated unexpectedly",
                    )
                });
            }
            if !self.workers.contains_key(&worker_id) {
                task.abort();
                self.cancel_worker_fetch_upload_connection((worker_id, request_id));
                return Err(NativeEngineError::Worker {
                    operation: "Worker fetch request upload".into(),
                    reason: "worker terminated while its request body was in flight".into(),
                });
            }

            let mut disconnected = false;
            let demand = if let Some(connection) = self
                .worker_fetch_upload_connections
                .get_mut(&(worker_id, request_id))
            {
                match connection.events.try_recv() {
                    Ok(NativeFetchUploadEvent::Demand) => {
                        connection.demand_pending = true;
                        true
                    }
                    Err(tokio::sync::mpsc::error::TryRecvError::Empty) => false,
                    Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => {
                        disconnected = true;
                        false
                    }
                }
            } else {
                false
            };
            if disconnected {
                task.abort();
                self.cancel_worker_fetch_upload_connection((worker_id, request_id));
                return Err(NativeEngineError::Network {
                    operation: "Worker fetch request upload".into(),
                    reason: "Worker fetch request upload task is unavailable".into(),
                });
            }
            if demand {
                let evaluation = if self.workers.contains_key(&worker_id) {
                    self.evaluate_worker_with_loader(worker_id, loader, |worker| {
                        worker.evaluate_fetch_upload_event(
                            worker_id,
                            request_id,
                            &serde_json::json!({"type": "demand"}),
                        )
                    })
                } else {
                    task.abort();
                    self.cancel_worker_fetch_upload_connection((worker_id, request_id));
                    return Err(NativeEngineError::Worker {
                        operation: "Worker fetch request upload".into(),
                        reason: "worker terminated while its request body was in flight".into(),
                    });
                };
                match evaluation {
                    Ok(evaluation) => {
                        if let Err(error) =
                            Box::pin(self.collect_worker_evaluation(worker_id, evaluation, loader))
                                .await
                        {
                            task.abort();
                            self.cancel_worker_fetch_upload_connection((worker_id, request_id));
                            return Err(error);
                        }
                    }
                    Err(error) => {
                        task.abort();
                        self.cancel_worker_fetch_upload_connection((worker_id, request_id));
                        return Err(error);
                    }
                }
            } else {
                tokio::task::yield_now().await;
            }
        }
    }

    async fn open_worker_fetch_upload(
        &mut self,
        worker_id: u32,
        request_id: u32,
        worker_url: String,
        href: String,
        method: NativeFetchMethod,
        headers: BTreeMap<String, String>,
        content_type: Option<String>,
        credentials: bool,
        cors_mode: NativeCorsMode,
        redirect_mode: NativeFetchRedirectMode,
        cache_mode: NativeFetchCacheMode,
        timeout: Option<Duration>,
        loader: &mut NativeResourceLoader,
    ) -> Result<Result<NativeFetchResponseStream, NativeEngineError>, NativeEngineError> {
        let upload_key = (worker_id, request_id);
        if self
            .worker_fetch_upload_connections
            .contains_key(&upload_key)
        {
            return Err(NativeEngineError::Network {
                operation: "Worker fetch request upload".into(),
                reason: "Worker fetch request upload identifier is already active".into(),
            });
        }
        if self.worker_fetch_upload_connections.len() >= MAX_NATIVE_WORKER_FETCH_UPLOADS {
            return Err(NativeEngineError::limit(
                "native Worker fetch request uploads",
                MAX_NATIVE_WORKER_FETCH_UPLOADS,
                self.worker_fetch_upload_connections.len().saturating_add(1),
            ));
        }
        let (upload_connection, upload_source) = spawn_native_fetch_upload_source();
        self.worker_fetch_upload_connections
            .insert(upload_key, upload_connection);
        if is_network_url(&worker_url) {
            let request_body = upload_source.into_body();
            let task_loader = loader.clone();
            let task = tokio::spawn(async move {
                let mut task_loader = task_loader;
                let result = task_loader
                    .open_fetch_response_stream_with_body_async(
                        NativeFetchRequest {
                            document_url: &worker_url,
                            href: &href,
                            method,
                            body: None,
                            content_type,
                            request_headers: headers,
                            credentials,
                            cors_mode,
                            redirect_mode,
                            cache_mode,
                            timeout,
                            max_response_bytes: None,
                        },
                        Some(request_body),
                    )
                    .await;
                (result, task_loader)
            });
            let (opened, task_loader) = self
                .drive_worker_fetch_upload_task(
                    worker_id,
                    request_id,
                    task,
                    loader,
                    "Worker fetch request upload task",
                )
                .await?;
            self.cancel_worker_fetch_upload_connection(upload_key);
            loader.merge_fetch_task_state(task_loader)?;
            return Ok(opened);
        }

        let task = tokio::spawn(async move {
            upload_source
                .collect(MAX_NATIVE_FORM_BODY_BYTES)
                .await
                .map_err(|reason| NativeEngineError::Network {
                    operation: "fixture Worker fetch request upload".into(),
                    reason,
                })
        });
        let body = self
            .drive_worker_fetch_upload_task(
                worker_id,
                request_id,
                task,
                loader,
                "fixture Worker fetch request upload task",
            )
            .await??;
        self.cancel_worker_fetch_upload_connection(upload_key);
        let opened = loader
            .open_fetch_response_stream_async(NativeFetchRequest {
                document_url: &worker_url,
                href: &href,
                method,
                body: Some(NativeRequestBody::Bytes(body)),
                content_type,
                request_headers: headers,
                credentials,
                cors_mode,
                redirect_mode,
                cache_mode,
                timeout,
                max_response_bytes: None,
            })
            .await;
        Ok(opened)
    }

    fn worker_fetch_opened_payload(
        &mut self,
        worker_id: u32,
        request_id: u32,
        opened: Result<NativeFetchResponseStream, NativeEngineError>,
    ) -> serde_json::Value {
        match opened {
            Ok(mut opened)
                if !opened.response.opaque
                    && !opened.response.opaque_redirect
                    && (opened.body.is_some() || opened.cached_body.is_some()) =>
            {
                let stream_key = (worker_id, request_id);
                if self
                    .worker_fetch_stream_connections
                    .contains_key(&stream_key)
                {
                    worker_fetch_response_payload(Err(NativeEngineError::Network {
                        operation: "native Worker fetch response stream".into(),
                        reason: "fetch response stream identifier is already active".into(),
                    }))
                } else if self.worker_fetch_stream_connections.len()
                    >= MAX_NATIVE_WORKER_FETCH_STREAMS
                {
                    worker_fetch_response_payload(Err(NativeEngineError::limit(
                        "native Worker fetch response streams",
                        MAX_NATIVE_WORKER_FETCH_STREAMS,
                        self.worker_fetch_stream_connections.len().saturating_add(1),
                    )))
                } else {
                    let response = opened.response;
                    let stream = if let Some(body) = opened.body.take() {
                        spawn_native_fetch_stream(body, opened.max_response_bytes)
                    } else {
                        spawn_native_fetch_bytes_stream(
                            opened
                                .cached_body
                                .take()
                                .expect("Worker fetch stream cached body is present"),
                            opened.max_response_bytes,
                        )
                    };
                    self.worker_fetch_stream_connections
                        .insert(stream_key, stream);
                    worker_fetch_response_stream_payload(response, request_id)
                }
            }
            Ok(mut opened) => {
                if let Some(body) = opened.cached_body.take() {
                    opened.response.body = body;
                }
                worker_fetch_response_payload(Ok(opened.response))
            }
            Err(error) => worker_fetch_response_payload(Err(error)),
        }
    }

    async fn resolve_worker_fetch(
        &mut self,
        worker_id: u32,
        command: NativeScriptCommand,
        loader: &mut NativeResourceLoader,
    ) -> Result<NativeScriptEvaluation, NativeEngineError> {
        let NativeScriptCommand::Fetch {
            request_id,
            worker_id: Some(command_worker_id),
            href,
            credentials,
            method,
            headers,
            body,
            body_base64,
            content_type,
            mode,
            redirect,
            cache,
            timeout_ms,
            upload_stream_id,
            destination,
        } = command
        else {
            return Err(NativeEngineError::invalid(
                "native Worker fetch command",
                "command was not a worker fetch",
            ));
        };
        if command_worker_id != worker_id {
            return Err(NativeEngineError::invalid(
                "native Worker fetch command",
                "worker id does not match the owning worker",
            ));
        }
        if destination.is_some() {
            return Err(NativeEngineError::invalid(
                "native Worker fetch destination",
                "worker fetch destinations are not supported",
            ));
        }
        if request_id == 0 {
            return Err(NativeEngineError::invalid(
                "native Worker fetch request id",
                "must be positive",
            ));
        }
        if timeout_ms.is_some_and(|value| value > MAX_NATIVE_XHR_TIMEOUT_MS) {
            return Err(NativeEngineError::invalid(
                "native Worker fetch timeout",
                "must not exceed the native XHR timeout limit",
            ));
        }
        let method = NativeFetchMethod::from_fetch_method(&method)?;
        let cors_mode = match mode.as_deref().unwrap_or("cors") {
            "cors" => NativeCorsMode::Cors,
            "no-cors" => NativeCorsMode::NoCors,
            "same-origin" => NativeCorsMode::SameOrigin,
            _ => {
                return Err(NativeEngineError::invalid(
                    "native Worker fetch mode",
                    "must be cors, no-cors, or same-origin",
                ));
            }
        };
        let redirect_mode = match redirect.as_deref().unwrap_or("follow") {
            "follow" => NativeFetchRedirectMode::Follow,
            "error" => NativeFetchRedirectMode::Error,
            "manual" => NativeFetchRedirectMode::Manual,
            _ => {
                return Err(NativeEngineError::invalid(
                    "native Worker fetch redirect mode",
                    "must be follow, error, or manual",
                ));
            }
        };
        let cache_mode = NativeFetchCacheMode::from_option(cache.as_deref())?;
        let body = if let Some(upload_stream_id) = upload_stream_id {
            if upload_stream_id != request_id {
                return Err(NativeEngineError::invalid(
                    "Worker fetch request upload stream",
                    "upload stream identifier must match its fetch request",
                ));
            }
            if body.is_some() || body_base64.is_some() {
                return Err(NativeEngineError::invalid(
                    "Worker fetch request upload stream",
                    "streaming fetch requests must not also carry a buffered body",
                ));
            }
            None
        } else {
            match body_base64 {
                Some(encoded) => Some(NativeRequestBody::Bytes(
                    base64::engine::general_purpose::STANDARD
                        .decode(encoded)
                        .map_err(|_| {
                            NativeEngineError::invalid(
                                "native Worker fetch binary body",
                                "must be valid base64",
                            )
                        })?,
                )),
                None => body.map(NativeRequestBody::Text),
            }
        };
        let worker_url = {
            let worker = self.workers.get(&worker_id).ok_or_else(|| {
                NativeEngineError::invalid("native Worker fetch", "worker no longer exists")
            })?;
            worker.url.clone()
        };
        let payload = if let Some(upload_stream_id) = upload_stream_id {
            if !self.stream_worker_fetches {
                worker_fetch_response_payload(Err(NativeEngineError::UnsupportedUrl {
                    reason: "streaming Worker request bodies require the native stream host".into(),
                }))
            } else {
                let opened = self
                    .open_worker_fetch_upload(
                        worker_id,
                        upload_stream_id,
                        worker_url.clone(),
                        href.clone(),
                        method,
                        headers,
                        content_type,
                        credentials,
                        cors_mode,
                        redirect_mode,
                        cache_mode,
                        timeout_ms.map(|value| Duration::from_millis(u64::from(value))),
                        loader,
                    )
                    .await?;
                match opened {
                    Ok(opened) => {
                        self.worker_fetch_opened_payload(worker_id, request_id, Ok(opened))
                    }
                    Err(error) => worker_fetch_response_payload(Err(error)),
                }
            }
        } else {
            let request = NativeFetchRequest {
                document_url: &worker_url,
                href: &href,
                method,
                body,
                content_type,
                request_headers: headers,
                credentials,
                cors_mode,
                redirect_mode,
                cache_mode,
                timeout: timeout_ms.map(|value| Duration::from_millis(u64::from(value))),
                max_response_bytes: None,
            };
            if self.stream_worker_fetches {
                self.worker_fetch_opened_payload(
                    worker_id,
                    request_id,
                    loader.open_fetch_response_stream_async(request).await,
                )
            } else {
                worker_fetch_response_payload(
                    loader.fetch_request_with_headers_async(request).await,
                )
            }
        };
        self.evaluate_worker_with_loader(worker_id, loader, |worker| {
            worker.evaluate_turn_with_event(
                worker_id,
                NativeWorkerDispatch::Fetch {
                    request_id,
                    payload: &payload,
                },
            )
        })
    }

    fn queue_error(
        &mut self,
        worker_id: u32,
        worker_url: &str,
        error: &str,
    ) -> Result<(), NativeEngineError> {
        let mut message: String = error
            .chars()
            .take(MAX_NATIVE_SCRIPT_BYTES.min(4096))
            .collect();
        if message.is_empty() {
            message = "native Worker failed".into();
        }
        self.queue_message(NativeWorkerMessage {
            worker_id,
            data: serde_json::Value::Null,
            error: Some(if worker_url.is_empty() {
                message
            } else {
                format!("{message} ({worker_url})")
            }),
            transfer_ports: Vec::new(),
            object_urls: Vec::new(),
        })
    }

    fn queue_message(&mut self, message: NativeWorkerMessage) -> Result<(), NativeEngineError> {
        validate_message_port_transfers(&message.transfer_ports)?;
        validate_native_object_url_transfers(&message.object_urls)?;
        validate_native_message_payload(
            &serde_json::json!({
                "data": &message.data,
                "error": &message.error,
                "transfer_ports": &message.transfer_ports,
                "object_urls": &message.object_urls,
            }),
            "native Worker message",
        )?;
        if self.pending_messages.len() >= MAX_NATIVE_WORKER_MESSAGES {
            return Err(NativeEngineError::limit(
                "native Worker message queue",
                MAX_NATIVE_WORKER_MESSAGES,
                self.pending_messages.len().saturating_add(1),
            ));
        }
        self.pending_messages.push_back(message);
        Ok(())
    }

    async fn load_worker_script_graph(
        &self,
        loader: &mut NativeResourceLoader,
        root: NativeScriptResource,
    ) -> Result<(String, BTreeMap<String, usize>), NativeEngineError> {
        struct PendingWorkerScript {
            resource: NativeScriptResource,
            imports: Vec<String>,
            next_import: usize,
        }

        if root.body.is_empty() {
            return Err(NativeEngineError::invalid(
                "worker script source",
                "must not be empty",
            ));
        }
        let root_imports = static_worker_import_specifiers(&root.body)?;
        let mut stack = vec![PendingWorkerScript {
            resource: root,
            imports: root_imports,
            next_import: 0,
        }];
        let mut import_script_counts = BTreeMap::<String, usize>::new();
        let mut import_edges = 0usize;
        let mut combined_source = String::new();
        while !stack.is_empty() {
            let next_import = stack.last_mut().and_then(|frame| {
                if frame.next_import >= frame.imports.len() {
                    return None;
                }
                let specifier = frame.imports[frame.next_import].clone();
                frame.next_import += 1;
                Some((frame.resource.url.clone(), specifier))
            });
            if let Some((parent_url, specifier)) = next_import {
                import_edges = import_edges.saturating_add(1);
                if import_edges > MAX_NATIVE_MODULE_IMPORTS {
                    return Err(NativeEngineError::limit(
                        "native worker importScripts graph",
                        MAX_NATIVE_MODULE_IMPORTS,
                        import_edges,
                    ));
                }
                let imported = loader
                    .load_worker_async(&parent_url, &specifier, MAX_NATIVE_SCRIPT_BYTES)
                    .await?
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "worker importScripts".into(),
                        reason: format!(
                            "worker importScripts dependency {specifier:?} was blocked or unavailable"
                        ),
                    })?;
                if stack.iter().any(|entry| entry.resource.url == imported.url) {
                    return Err(NativeEngineError::Network {
                        operation: "worker importScripts".into(),
                        reason: "worker importScripts dependency graph contains a cycle".into(),
                    });
                }
                import_script_counts
                    .entry(specifier)
                    .and_modify(|count| *count = count.saturating_add(1))
                    .or_insert(1);
                let imports = static_worker_import_specifiers(&imported.body)?;
                stack.push(PendingWorkerScript {
                    resource: imported,
                    imports,
                    next_import: 0,
                });
                continue;
            }
            let frame = stack.pop().expect("worker script stack was non-empty");
            let next_length = combined_source
                .len()
                .saturating_add(frame.resource.body.len());
            if next_length > MAX_NATIVE_SCRIPT_BYTES {
                return Err(NativeEngineError::limit(
                    "combined worker importScripts source",
                    MAX_NATIVE_SCRIPT_BYTES,
                    next_length,
                ));
            }
            combined_source.push_str(&frame.resource.body);
            combined_source.push_str("\n;");
        }
        Ok((combined_source, import_script_counts))
    }

    async fn load_worker_module_graph(
        &self,
        loader: &mut NativeResourceLoader,
        owner_url: &str,
        root: NativeScriptResource,
    ) -> Result<BTreeMap<String, String>, NativeEngineError> {
        if root.body.is_empty() {
            return Err(NativeEngineError::invalid(
                "worker module source",
                "must not be empty",
            ));
        }
        let mut sources = BTreeMap::from([(root.url.clone(), root.body.clone())]);
        let mut pending = VecDeque::from([(root.url, root.body)]);
        let mut total_bytes = sources.values().map(String::len).sum::<usize>();
        let mut import_edges = 0usize;
        while let Some((module_url, module_source)) = pending.pop_front() {
            let mut specifiers = static_module_specifiers(&module_source)?;
            specifiers.extend(literal_dynamic_module_specifiers(&module_source));
            for specifier in specifiers {
                import_edges = import_edges.saturating_add(1);
                if import_edges > MAX_NATIVE_MODULE_IMPORTS {
                    return Err(NativeEngineError::limit(
                        "native Worker module imports",
                        MAX_NATIVE_MODULE_IMPORTS,
                        import_edges,
                    ));
                }
                let target = resolve_worker_module_specifier(&module_url, &specifier)?;
                if sources.contains_key(&target) {
                    continue;
                }
                if sources.len() >= MAX_NATIVE_MODULE_IMPORTS {
                    return Err(NativeEngineError::limit(
                        "native Worker module graph entries",
                        MAX_NATIVE_MODULE_IMPORTS,
                        sources.len().saturating_add(1),
                    ));
                }
                let resource = loader
                    .load_worker_async(owner_url, &target, MAX_NATIVE_SCRIPT_BYTES)
                    .await?
                    .ok_or_else(|| NativeEngineError::Network {
                        operation: "native Worker module dependency".into(),
                        reason: format!(
                            "Worker module dependency {specifier:?} was blocked or unavailable"
                        ),
                    })?;
                if resource.body.is_empty() {
                    return Err(NativeEngineError::invalid(
                        "worker module source",
                        "must not be empty",
                    ));
                }
                total_bytes = total_bytes.saturating_add(resource.body.len());
                if total_bytes > MAX_NATIVE_SCRIPT_BYTES.saturating_mul(MAX_NATIVE_MODULE_IMPORTS) {
                    return Err(NativeEngineError::limit(
                        "native Worker module graph bytes",
                        MAX_NATIVE_SCRIPT_BYTES.saturating_mul(MAX_NATIVE_MODULE_IMPORTS),
                        total_bytes,
                    ));
                }
                let name = resource.url;
                let source = resource.body;
                if sources.insert(name.clone(), source.clone()).is_none() {
                    pending.push_back((name, source));
                }
            }
        }
        Ok(sources)
    }
}

pub(crate) async fn load_service_worker_source(
    loader: &mut NativeResourceLoader,
    owner_url: &str,
    resource: NativeScriptResource,
    is_module: bool,
) -> Result<(String, BTreeMap<String, usize>, BTreeMap<String, String>), NativeEngineError> {
    let registry = NativeWorkerRegistry::new();
    if is_module {
        let module_sources = registry
            .load_worker_module_graph(loader, owner_url, resource.clone())
            .await?;
        Ok((resource.body, BTreeMap::new(), module_sources))
    } else {
        let (source, import_script_counts) =
            registry.load_worker_script_graph(loader, resource).await?;
        Ok((source, import_script_counts, BTreeMap::new()))
    }
}

fn resolve_worker_module_specifier(
    module_url: &str,
    specifier: &str,
) -> Result<String, NativeEngineError> {
    let is_absolute = specifier.starts_with("http://")
        || specifier.starts_with("https://")
        || specifier.starts_with("fixture://")
        || specifier
            .get(..5)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("file:"));
    if !is_absolute
        && !specifier.starts_with("./")
        && !specifier.starts_with("../")
        && !specifier.starts_with('/')
        && !specifier.starts_with("//")
    {
        return Err(NativeEngineError::UnsupportedUrl {
            reason: "bare Worker module specifiers require an import map".into(),
        });
    }
    let mut base = Url::parse(module_url).map_err(|_| NativeEngineError::UnsupportedUrl {
        reason: "Worker module owner URL is not valid URL syntax".into(),
    })?;
    base.set_fragment(None);
    let mut target = if is_absolute {
        Url::parse(specifier)
    } else {
        base.join(specifier)
    }
    .map_err(|_| NativeEngineError::UnsupportedUrl {
        reason: "Worker module specifier could not be resolved against its owner".into(),
    })?;
    if !target.username().is_empty() || target.password().is_some() {
        return Err(NativeEngineError::UnsupportedUrl {
            reason: "Worker module URL must not contain credentials".into(),
        });
    }
    target.set_fragment(None);
    if !matches!(target.scheme(), "http" | "https" | "fixture" | "file") {
        return Err(NativeEngineError::UnsupportedUrl {
            reason: "Worker module URL must use HTTP(S), a registered fixture, or a rooted file"
                .into(),
        });
    }
    Ok(target.to_string())
}

fn worker_fetch_response_payload(
    result: Result<NativeFetchResponse, NativeEngineError>,
) -> serde_json::Value {
    match result {
        Ok(response) => serde_json::json!({
            "url": response.url,
            "status": response.status,
            "statusText": response.status_text,
            "contentType": response.content_type,
            "headers": response.headers,
            "body": String::from_utf8_lossy(&response.body),
            "bodyBase64": base64::engine::general_purpose::STANDARD.encode(&response.body),
            "redirected": response.redirected,
            "opaque": response.opaque,
            "opaqueRedirect": response.opaque_redirect,
        }),
        Err(error) => serde_json::json!({
            "error": error.to_string(),
            "timeout": matches!(
                &error,
                NativeEngineError::Network { reason, .. } if reason == "request timed out"
            ),
        }),
    }
}

fn worker_fetch_response_stream_payload(
    response: NativeFetchResponse,
    stream_id: u32,
) -> serde_json::Value {
    let mut payload = worker_fetch_response_payload(Ok(response));
    if let Some(object) = payload.as_object_mut() {
        object.insert("bodyStreamId".into(), serde_json::Value::from(stream_id));
    }
    payload
}

fn worker_fetch_stream_event_payload(event: &NativeFetchStreamEvent) -> serde_json::Value {
    match event {
        NativeFetchStreamEvent::Chunk { data } => serde_json::json!({
            "type": "chunk",
            "dataBase64": base64::engine::general_purpose::STANDARD.encode(data),
        }),
        NativeFetchStreamEvent::End => serde_json::json!({"type": "end"}),
        NativeFetchStreamEvent::Error { message } => {
            serde_json::json!({"type": "error", "message": message})
        }
    }
}

/// A browser-context creation request emitted by `window.open`.
///
/// The JavaScript realm never receives a direct native target handle. The
/// request crosses the engine boundary and is materialized by the target
/// owner, which keeps popup creation and named-context reuse serialized with
/// the rest of the browser topology.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
pub(crate) struct NativePopupRequest {
    pub(crate) url: String,
    pub(crate) target: String,
    #[serde(default)]
    pub(crate) method: NativeNavigationMethod,
    #[serde(default)]
    pub(crate) body: Option<NativeRequestBody>,
    #[serde(default)]
    pub(crate) body_content_type: Option<String>,
    #[serde(default)]
    pub(crate) handle: Option<String>,
    #[serde(default)]
    pub(crate) object_url: Option<NativeObjectUrlResource>,
    #[serde(default, skip_serializing)]
    pub(crate) source_context_id: String,
}

/// A bounded cross-context message emitted by a native page realm.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub(crate) struct NativePostMessageRequest {
    pub(crate) target: String,
    pub(crate) target_origin: String,
    pub(crate) data: serde_json::Value,
    #[serde(default)]
    pub(crate) target_context_id: Option<String>,
    #[serde(default)]
    pub(crate) transfer_ports: Vec<NativeMessagePortTransfer>,
    /// Blob URL snapshots captured while the source realm still owns the URL.
    #[serde(default)]
    pub(crate) object_urls: Vec<NativeObjectUrlTransfer>,
    #[serde(default, skip_serializing)]
    pub(crate) source_context_id: String,
    #[serde(default, skip_serializing)]
    pub(crate) source_origin: String,
    #[serde(default, skip_serializing)]
    pub(crate) source_frame_id: String,
}

/// A bounded request for the parent target owner to close a WindowProxy target.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
pub(crate) struct NativeWindowCloseRequest {
    pub(crate) target: String,
    #[serde(default)]
    pub(crate) target_context_id: Option<String>,
    #[serde(default, skip_serializing)]
    pub(crate) source_context_id: String,
}

/// A bounded request for the parent target owner to navigate a WindowProxy.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
pub(crate) struct NativeWindowNavigationRequest {
    pub(crate) target: String,
    #[serde(default)]
    pub(crate) target_context_id: Option<String>,
    pub(crate) href: String,
    #[serde(default)]
    pub(crate) method: NativeNavigationMethod,
    #[serde(default)]
    pub(crate) body: Option<NativeRequestBody>,
    #[serde(default)]
    pub(crate) body_content_type: Option<String>,
    #[serde(default)]
    pub(crate) replace: bool,
    #[serde(default)]
    pub(crate) object_url: Option<NativeObjectUrlResource>,
    #[serde(default, skip_serializing)]
    pub(crate) source_context_id: String,
}

